from mut import *
import json
C = json.load(open(os.path.join(HERE, "..", "ctx.json")))
ids = json.load(open(os.path.join(HERE, "..", "ids.json")))
S = "fixtures"
guard()
lid = ids["limit_buy_mis_reliance_far_below"]
m = dict(strategy=S, exchange="NSE", symbol="RELIANCE", orderid=lid, action="BUY", product="MIS", pricetype="LIMIT", price=round(C["rel_ltp"]*0.82, 1), quantity=2, disclosed_quantity=0, trigger_price=0)
P("modifyorder", "open_limit_price_and_qty", k(**m))
P("orderstatus", "after_modify", k(strategy=S, orderid=lid))
P("modifyorder", "sl_order_trigger", k(**dict(m, orderid=ids["sl_buy_mis_reliance"], pricetype="SL", quantity=1, price=round(C["rel_ltp"]*1.08, 1), trigger_price=round(C["rel_ltp"]*1.07, 1))))
P("modifyorder", "error_unknown_orderid", k(**dict(m, orderid="99999999999999")))
P("modifyorder", "error_completed_order", k(**dict(m, orderid=ids["market_buy_mis_reliance"], pricetype="MARKET", price=0, quantity=5)))
mm = dict(m); mm.pop("price")
P("modifyorder", "error_missing_price", k(**mm))
P("modifyorder", "error_negative_price", k(**dict(m, price=-1)))
# cancel
guard()
cid = ids["limit_sell_mis_reliance_far_above"]
P("cancelorder", "open_limit", k(strategy=S, orderid=cid))
P("orderstatus", "after_cancel", k(strategy=S, orderid=cid))
P("cancelorder", "error_already_cancelled", k(strategy=S, orderid=cid))
P("cancelorder", "error_completed_order", k(strategy=S, orderid=ids["market_buy_mis_reliance"]))
P("cancelorder", "error_unknown_orderid", k(strategy=S, orderid="99999999999999"))
P("cancelorder", "error_missing_orderid", k(strategy=S))
P("modifyorder", "error_cancelled_order", k(**dict(m, orderid=cid, action="SELL")))
# smart orders on INFY MIS (fresh symbol)
guard()
sm = dict(strategy=S, exchange="NSE", symbol="INFY", product="MIS", pricetype="MARKET")
P("placesmartorder", "open_from_flat_to_10", k(**sm, action="BUY", quantity=10, position_size=10), note="flat -> +10 (BUY 10)")
P("openposition", "infy_after_smart_open", k(strategy=S, symbol="INFY", exchange="NSE", product="MIS"))
P("placesmartorder", "raise_10_to_15", k(**sm, action="BUY", quantity=5, position_size=15), note="+10 -> +15")
P("placesmartorder", "reduce_15_to_5", k(**sm, action="SELL", quantity=10, position_size=5), note="+15 -> +5")
P("placesmartorder", "no_action_already_at_5", k(**sm, action="BUY", quantity=0, position_size=5), note="position already matches")
P("placesmartorder", "to_zero", k(**sm, action="SELL", quantity=0, position_size=0), note="+5 -> 0")
P("placesmartorder", "flat_to_short_minus_3", k(**sm, action="SELL", quantity=3, position_size=-3), note="0 -> -3")
P("openposition", "infy_after_smart_short", k(strategy=S, symbol="INFY", exchange="NSE", product="MIS"))
P("placesmartorder", "error_missing_position_size", k(**sm, action="BUY", quantity=1))
P("placesmartorder", "error_unknown_symbol", k(**dict(sm, symbol="NOTASYMBOL"), action="BUY", quantity=1, position_size=1))
